const PIZZA_HOT_API_URL = "https://script.google.com/macros/s/AKfycby5pD8nlMt62GdcAeHZKTj7cKF4xFOigK_Qhn7JV778mCIbwp0sO2eHKSnIt6TL57ZM/exec?api=PIZZA_HOT",
    PIZZA_HOT_CACHE_KEY = "pizza_hot_cache", PIZZA_HOT_CACHE_TIME_KEY = "pizza_hot_cache_time", CACHE_DURATION = 36e5, pizzaElements = {};

async function loadPizzaOffers(e = !1) {
    setPizzaState("loading");
    try {
        if (!e) {
            const e = localStorage.getItem("pizza_hot_cache"), t = localStorage.getItem("pizza_hot_cache_time");
            if (e && t && Date.now() - Number(t) < 36e5) {
                console.log("Pizza Hot 使用本機快取資料");
                return void renderPizzaOffers(JSON.parse(e).filter(isValidPizzaOffer))
            }
        }
        const t = await fetch(PIZZA_HOT_API_URL, {method: "GET", redirect: "follow", cache: "no-store"});
        if (!t.ok) throw new Error(`HTTP ${t.status}`);
        const a = await t.json();
        if (!Array.isArray(a)) throw new Error("API response is not an array");
        localStorage.setItem("pizza_hot_cache", JSON.stringify(a)), localStorage.setItem("pizza_hot_cache_time", String(Date.now()));
        renderPizzaOffers(a.filter(isValidPizzaOffer))
    } catch (e) {
        console.error("Pizza Hot API 載入失敗", {name: e.name, message: e.message, stack: e.stack}), setPizzaState("error")
    }
}

function isValidPizzaOffer(e) {
    return e && "object" == typeof e && e.code && e.detail
}

function renderPizzaOffers(e) {
    if (pizzaElements.grid.replaceChildren(), 0 === e.length) return void setPizzaState("empty");
    const t = document.createDocumentFragment();
    e.forEach(e => {
        const a = document.createElement("article");
        a.className = "pizza-card";
        const n = document.createElement("p");
        n.className = "pizza-card__code", n.textContent = `優惠代碼 ${String(e.code)}`;
        const r = document.createElement("p");
        r.className = "pizza-card__detail", r.textContent = String(e.detail);
        const o = document.createElement("p");
        o.className = "pizza-card__date", o.textContent = e.endDate ? `優惠截止日期${formatPizzaDate(e.endDate)}` : "優惠截止日期未提供", a.append(n, r, o), t.append(a)
    }), pizzaElements.grid.append(t), pizzaElements.count.textContent = `目前共有 ${e.length} 組優惠`, setPizzaState("success")
}

function formatPizzaDate(e) {
    const t = String(e).match(/^(\d{4})-(\d{2})-(\d{2})$/);
    return t ? `${t[1]}/${t[2]}/${t[3]}` : String(e)
}

function setPizzaState(e) {
    pizzaElements.loading.hidden = "loading" !== e, pizzaElements.error.hidden = "error" !== e, pizzaElements.empty.hidden = "empty" !== e, pizzaElements.reload.hidden = "error" !== e, "loading" === e && (pizzaElements.grid.replaceChildren(), pizzaElements.count.textContent = "正在取得優惠資料..."), "error" === e && (pizzaElements.grid.replaceChildren(), pizzaElements.count.textContent = "優惠資料載入失敗"), "empty" === e && (pizzaElements.count.textContent = "目前沒有優惠資料")
}

document.addEventListener("DOMContentLoaded", () => {
    pizzaElements.grid = document.querySelector("#pizza-card-grid"), pizzaElements.loading = document.querySelector("#pizza-loading"), pizzaElements.error = document.querySelector("#pizza-error"), pizzaElements.empty = document.querySelector("#pizza-empty"), pizzaElements.count = document.querySelector("#pizza-result-count"), pizzaElements.reload = document.querySelector("#pizza-reload"), pizzaElements.reload.addEventListener("click", () => {
        localStorage.removeItem("pizza_hot_cache"), localStorage.removeItem("pizza_hot_cache_time"), loadPizzaOffers(!0)
    }), loadPizzaOffers()
});